#include "Core.h"
#include <iostream>
int main(int argc,char**argv){try{std::filesystem::path out=argc>1?argv[1]:"Library";for(auto d:{"Presets","MIDI","Basslines","Kicks"})std::filesystem::create_directories(out/d);auto f=psy::factories();for(int i=0;i<32;++i){auto name=std::to_string(i+1)+"_"+f[size_t(i)].name;psy::savePreset(out/"Presets"/(name+".psyfactory"),f[size_t(i)]);psy::midi(out/"MIDI"/(name+".mid"),f[size_t(i)].pattern);auto a=psy::render(f[size_t(i)]);psy::wav(out/"Basslines"/(name+".wav"),a,48000);std::cout<<name<<" rendered\n";}for(int i=0;i<10;++i){psy::Kick k;k.p=psy::kickPreset(i);k.trigger();std::vector<float>a(96000);for(auto&v:a)v=k.tick(48000);psy::wav(out/"Kicks"/(std::to_string(i+1)+"_PsyKick.wav"),a,48000);}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
